package com.morphlabs.morph.core.academy.deck

import com.morphlabs.morph.core.academy.Action
import com.morphlabs.morph.core.academy.Card
import com.morphlabs.morph.core.academy.Signal
import com.morphlabs.morph.core.academy.Track

internal object EconomyCards {
    private val T = Track.ECONOMY
    val cards: List<Card> = listOf(
        // ---------- Level 1: Rookie ----------
        quiz("ec-inflation-what", T, 1, "What does \"inflation\" actually mean?",
            listOf("Prices in general rise, so each shilling buys less", "The price of one item, like sukuma, goes up", "The government prints new banknotes", "The shilling weakens against the dollar"), 0,
            "Inflation is a broad, ongoing rise in prices across the economy. One item getting dearer is just a price change; inflation is when the whole basket climbs.",
            source = "KNBS"),
        concept("ec-cpi", T, 1, "How does Kenya measure inflation each month?",
            "KNBS prices a fixed basket of goods and services (food, transport, housing, energy and more) every month. The Consumer Price Index (CPI) tracks that basket; inflation is how much it costs versus the same month last year.",
            source = "KNBS"),
        concept("ec-inflation-target", T, 1, "What inflation rate is the Central Bank of Kenya aiming for?",
            "A target of 5%, with room of 2.5 points either side: 2.5% to 7.5%. Inside that band, CBK is broadly happy. Near the top, it gets nervous and may keep rates higher.",
            source = "CBK, 2026", timeSensitive = true),
        quiz("ec-supply-demand", T, 1, "A bumper harvest floods Wakulima market with tomatoes. What usually happens to the price?",
            listOf("It falls", "It rises", "It stays the same", "It doubles"), 0,
            "Supply jumped while demand stayed about the same, so sellers compete for buyers and the price drops. In a dry season the opposite happens.",
            source = "Basic economics"),
        concept("ec-two-causes", T, 1, "What are the two classic causes of inflation?",
            "Demand-pull: too much money chasing too few goods (people and government spending a lot). Cost-push: costs of making things rise (fuel, fertiliser, a weak shilling), so sellers pass them on.",
            source = "Basic economics"),
        quiz("ec-interest-rate", T, 1, "What is an interest rate, in plain terms?",
            listOf("The price of borrowing money for a period", "A tax on bank deposits", "A fee M-Pesa charges per transaction", "The profit a bank must share with CBK"), 0,
            "Interest is the price of using someone else's money over time. Borrowers pay it; savers and lenders earn it.",
            source = "CBK"),
        concept("ec-cbr-what", T, 1, "What is the Central Bank Rate (CBR)?",
            "It is CBK's main policy rate: the anchor for the rate banks charge each other overnight. Raise it and money gets dearer across the economy; cut it and borrowing gets cheaper.",
            source = "CBK"),
        quiz("ec-gdp", T, 1, "What does GDP (Gross Domestic Product) measure?",
            listOf("Value of all final goods and services a country produces", "Total money held in Kenyan banks", "Government tax collected in a year", "Value of all exports"), 0,
            "GDP adds up everything produced in the country in a period. Kenya's economy was about Ksh 17.6 trillion in 2025.",
            source = "KNBS Economic Survey 2026", timeSensitive = true),
        concept("ec-fuel-everything", T, 1, "Why does a fuel price rise make almost everything dearer?",
            "Fuel moves food from shamba to market, powers matatus and lorries, runs factories and some power plants. When it rises, transport, food and production costs rise, and sellers pass them on.",
            source = "KNBS CPI"),
        quiz("ec-epra", T, 1, "Who sets the maximum pump prices for petrol and diesel in Kenya?",
            listOf("EPRA, in a monthly review", "The Central Bank of Kenya", "Each petrol station", "KRA"), 0,
            "The Energy and Petroleum Regulatory Authority (EPRA) publishes price caps each month, running from the 15th to the 14th of the next month.",
            source = "EPRA, 2026"),
        quiz("ec-real-pay", T, 1, "Your pay rises 5% this year, but inflation is 7%. What happened to your real pay?",
            listOf("It fell by about 2%", "It rose by 5%", "It rose by 12%", "It stayed exactly the same"), 0,
            "Real pay is what your money can buy. Prices grew faster than your pay, so you can afford about 2% less than last year.",
            source = "Basic economics"),
        quiz("ec-recession", T, 1, "What is a common rule-of-thumb definition of a recession?",
            listOf("Two quarters in a row of shrinking real GDP", "Inflation above 10%", "The shilling falling 10%", "Unemployment above 5%"), 0,
            "Many economists use two consecutive quarters of falling real output as a quick test, though official bodies look at broader data too.",
            source = "IMF"),

        // ---------- Level 2: Hustler ----------
        quiz("ec-real-return", T, 2, "A money market fund pays 9% gross, 15% withholding tax applies, inflation is 6.8%. Real return?",
            listOf("About 0.8%", "About 9%", "About 2.2%", "About 7.7%"), 0,
            "After tax: 9% x 0.85 = 7.65%. Minus 6.8% inflation leaves roughly 0.8% of real growth. Fees would cut it further.",
            source = "KNBS, Sep 2026; KRA", timeSensitive = true),
        concept("ec-rule-70", T, 2, "If inflation runs at 7% a year, roughly how long until prices double?",
            "About 10 years. Rule of 70: divide 70 by the yearly rate. So a Ksh 100 loaf today would cost about Ksh 200 in a decade at 7%.",
            source = "Rule of 70"),
        quiz("ec-cbr-cut-effect", T, 2, "CBK cuts the CBR. What usually follows over the next months?",
            listOf("Loans get cheaper and MMF yields drift lower", "Loans get dearer and MMF yields jump", "Only the dollar rate changes", "Nothing until next year's budget"), 0,
            "A cut lowers the cost of money for banks. Lending rates and T-bill yields follow, and money market funds that hold bills slowly earn less.",
            source = "CBK"),
        concept("ec-cbr-now", T, 2, "Where is the CBR now, and why did CBK stop cutting?",
            "8.75% since February 2026, after 10 straight cuts from 13% (425 basis points). It held in April, June and August 2026 because oil prices from the Middle East conflict pushed inflation up.",
            source = "CBK MPC, Aug 2026", timeSensitive = true),
        quiz("ec-fuel-2026", T, 2, "In Oct 2026 Nairobi petrol rose Ksh 12.93 a litre. You buy 40 litres a month. Extra cost per month?",
            listOf("About Ksh 517", "About Ksh 129", "About Ksh 1,293", "About Ksh 52"), 0,
            "40 x 12.93 = Ksh 517.20 a month, about Ksh 6,200 a year, before the knock-on rise in fares and food.",
            source = "EPRA, Oct 2026", timeSensitive = true),
        concept("ec-food-weight", T, 2, "Headline inflation was 6.8% in Sept 2026, but food was 9.5%. Who feels it most?",
            "Households that spend most of their income on food. For them, \"their\" inflation is closer to 9% than 7%. Your personal inflation depends on what you actually buy.",
            source = "KNBS via Trading Economics, Sep 2026", timeSensitive = true),
        quiz("ec-gdp-2025", T, 2, "How fast did Kenya's real GDP grow in 2025?",
            listOf("4.6%", "1.2%", "8.9%", "-0.5%"), 0,
            "KNBS's 2026 Economic Survey put 2025 growth at 4.6%, slightly below 4.7% in 2024. Farming was hit by erratic rain; tourism and construction did well.",
            source = "KNBS Economic Survey 2026", timeSensitive = true),
        concept("ec-per-capita", T, 2, "If GDP grows 4.6% and the population grows about 2%, how much richer is the average person?",
            "Only about 2.6%. GDP per person is what matters for living standards. Fast population growth means the economy must grow quickly just to stand still.",
            source = "KNBS"),
        quiz("ec-inelastic", T, 2, "Petrol prices jump 6%. Why don't Kenyans cut fuel use by much in the short run?",
            listOf("Demand is inelastic: few quick substitutes", "Petrol is subsidised to zero", "Demand always rises with price", "People buy fuel in dollars"), 0,
            "Inelastic means demand barely responds to price. You still need the matatu to work. That's why fuel shocks feed so directly into inflation.",
            source = "Basic economics"),
        concept("ec-opportunity-cost", T, 2, "What is \"opportunity cost\"?",
            "The value of the best thing you gave up. Ksh 50,000 in a chama payout spent on a phone isn't just Ksh 50,000; it is also the stock or school fees it could have been.",
            source = "Basic economics"),
        quiz("ec-price-ceiling", T, 2, "A government caps a staple's price below what it costs to supply. Likely result?",
            listOf("Shortages and queues", "A surplus piling up", "Higher quality goods", "No effect on supply"), 0,
            "Below-cost prices make sellers supply less while buyers want more. The gap shows up as empty shelves, rationing or black markets.",
            source = "Basic economics"),
        you("ec-you-inflation-savings", T, 2, "At 7% inflation, how much buying power could your idle {savings} lose in a year?",
            "About 7% of {savings} in real terms, if it earns nothing. Cash sitting still is slowly melting. Compare what your savings earn after tax to the latest inflation figure.",
            tryThis = "Check what your savings account or MMF earns against this month's inflation", action = Action.ACCOUNTS),

        // ---------- Level 3: Pro ----------
        quiz("ec-fx-what", T, 3, "The rate goes from Ksh 129 to Ksh 160 per US dollar. What happened to the shilling?",
            listOf("It weakened: each dollar costs more shillings", "It strengthened", "Nothing, only the dollar changed", "Kenya changed its currency"), 0,
            "More shillings per dollar means a weaker shilling. Imports, fuel and dollar debts all get more expensive in Ksh.",
            source = "CBK"),
        concept("ec-fx-2024", T, 3, "What happened to the shilling in 2024?",
            "It hit a record low of about Ksh 160 per dollar in January 2024. A February Eurobond deal eased fears of default, and by early April it was near Ksh 129. It then held around Ksh 129 to 132 for over two years.",
            source = "The Star; CBK, 2024", timeSensitive = true),
        quiz("ec-fx-import-cost", T, 3, "A laptop costs USD 300. How much cheaper in Ksh at 129 per dollar than at 160?",
            listOf("Ksh 9,300", "Ksh 3,100", "Ksh 31,000", "Ksh 930"), 0,
            "300 x 160 = Ksh 48,000; 300 x 129 = Ksh 38,700. Difference: Ksh 9,300. Exchange rates quietly move the price of almost every import.",
            source = "Calculation"),
        concept("ec-cbr-transmission", T, 3, "How does a CBR change travel to your loan and your MMF?",
            "CBR steers the overnight interbank rate (KESONIA). That moves T-bill yields and bank funding costs. Banks reprice variable loans; MMFs earn more or less as they roll into new bills. It takes weeks to months.",
            source = "CBK"),
        quiz("ec-kesonia", T, 3, "Under CBK's revised model, how is a variable-rate shilling bank loan priced?",
            listOf("KESONIA plus a premium \"K\" for costs and your risk", "A flat 13% for everyone", "CBR plus 4% by law", "Whatever the bank chooses, with no disclosure"), 0,
            "New loans from Sept 2025, all existing ones by Feb 2026. Banks must publish their premiums, so you can compare lenders on the Total Cost of Credit portal.",
            source = "CBK, 2025", signals = setOf(Signal.HAS_DEBT), timeSensitive = true),
        quiz("ec-mmf-lag", T, 3, "CBK cuts the CBR, but your MMF yield only drops slowly. Why?",
            listOf("The fund still holds older, higher-yield bills until they mature", "MMFs are exempt from CBK policy", "Yields are fixed by law for a year", "The fund manager absorbs the cut"), 0,
            "Funds hold a mix of bills and deposits bought at older rates. As those mature and are replaced at lower yields, the fund's return eases down.",
            source = "CMA"),
        concept("ec-debt-stock", T, 3, "How big is Kenya's public debt?",
            "Roughly Ksh 13 trillion in 2026: about 7.2 trillion domestic, 5.8 trillion external. That is around 70% of GDP, well above Parliament's 55% anchor.",
            source = "CBK; National Treasury, 2026", timeSensitive = true),
        quiz("ec-eurobond", T, 3, "What is a Eurobond in Kenya's case?",
            listOf("A bond in foreign currency sold to international investors", "A loan from the European Union", "A bond only Europeans can buy", "A shilling bond listed on the NSE"), 0,
            "Kenya sells dollar bonds abroad. In Feb 2024 it raised USD 1.5bn at 10.375% to buy back most of a 6.875% bond due that June.",
            source = "Bloomberg, Feb 2024"),
        concept("ec-fx-debt-risk", T, 3, "Why does a weaker shilling make government debt worse?",
            "External debt is owed in dollars, euros and yen. If the shilling falls 20%, those debts cost 20% more shillings to repay, from the same tax revenue.",
            source = "National Treasury"),
        quiz("ec-remittances", T, 3, "Roughly how much did Kenyans abroad send home in 2025?",
            listOf("About USD 5 billion", "About USD 500 million", "About USD 50 billion", "About USD 1 billion"), 0,
            "About USD 5.04bn, a record, but growth slowed to 1.9%. Around half comes from the US, so US jobs matter to Kenya's dollar supply.",
            source = "CBK, Jan 2026", timeSensitive = true),
        concept("ec-trade-balance", T, 3, "Kenya imports more than it exports. How does it pay for the gap?",
            "Through other dollar inflows: remittances, tourism, services, foreign investment and borrowing. If those slow, pressure builds on the shilling.",
            source = "KNBS; CBK"),
        quiz("ec-debt-service", T, 3, "In FY2024/25, debt service took roughly what share of ordinary revenue?",
            listOf("About 69%", "About 15%", "About 35%", "More than 100%"), 0,
            "Around Ksh 1.72 trillion. When most tax goes to lenders, less is left for schools, roads and health, and pressure grows for new taxes.",
            source = "National Treasury, 2025", timeSensitive = true),

        // ---------- Level 4: Shark ----------
        concept("ec-mpc", T, 4, "Who decides the CBR, and how?",
            "The Monetary Policy Committee, set up under section 4D of the CBK Act and chaired by the Governor. It meets about every two months, reviews inflation, growth and the shilling, and announces a rate decision.",
            source = "CBK Act s.4D"),
        quiz("ec-mpc-hold-2026", T, 4, "Why did the MPC pause rate cuts in April 2026?",
            listOf("To watch second-round effects of higher oil prices", "Because the shilling hit Ksh 160", "Because the IMF banned cuts", "Because GDP was shrinking"), 0,
            "Oil prices jumped with the Middle East conflict. CBK worried fuel costs would spill into fares, food and wages before easing again.",
            source = "CBK MPC, Apr 2026", timeSensitive = true),
        concept("ec-second-round", T, 4, "What are \"second-round effects\" of a price shock?",
            "First round: pump prices rise. Second round: matatus raise fares, bakers raise bread prices, workers demand higher pay. If that spreads, a one-off shock becomes lasting inflation. Central banks fight round two.",
            source = "CBK"),
        quiz("ec-imf", T, 4, "What does an IMF programme usually involve?",
            listOf("Loans in exchange for policy reforms and reviews", "Free grants with no conditions", "The IMF taking over the Treasury", "Printing money for the government"), 0,
            "Kenya's USD 3.6bn programme ended in April 2025. Talks on a new one continued through 2026 without a deal as of October.",
            source = "IMF; Reuters, 2026", timeSensitive = true),
        concept("ec-finance-bill-2024", T, 4, "What happened with Kenya's Finance Bill 2024?",
            "It aimed to raise new taxes to cut borrowing. Youth-led protests grew; on 25 June 2024 protesters breached Parliament and many were killed. The next day President Ruto declined to sign it and it was withdrawn.",
            source = "Al Jazeera; NPR, Jun 2024"),
        quiz("ec-fb2024-measures", T, 4, "Which of these was proposed in the original Finance Bill 2024?",
            listOf("16% VAT on bread and a 2.5% motor vehicle tax", "Abolishing PAYE", "A 50% tax on M-Pesa", "Cutting VAT to zero"), 0,
            "Both were dropped in amendments before the vote, but anger over the wider bill and the cost of living kept growing.",
            source = "The EastAfrican, Jun 2024"),
        quiz("ec-money-creation", T, 4, "Where does most money in a modern economy come from?",
            listOf("Banks creating deposits when they make loans", "CBK printing notes", "Mining gold", "Taxes collected by KRA"), 0,
            "When a bank lends you Ksh 100,000 it credits your account: new money appears. Repaying the loan destroys it. The Bank of England explained this in 2014.",
            source = "McLeay, Radia & Thomas, BoE, 2014"),
        quiz("ec-bond-yield", T, 4, "A bond pays a fixed 12% coupon. Market rates then rise to 15%. What happens to its price?",
            listOf("It falls", "It rises", "It stays at face value", "It doubles"), 0,
            "Nobody pays full price for 12% when new bonds pay 15%, so the old bond's price drops until its yield matches. Price and yield move opposite.",
            source = "CFA Institute"),
        concept("ec-crowding-out", T, 4, "What is \"crowding out\", and how did Kenya see it in 2024?",
            "When the government borrows heavily at high rates, banks would rather lend to it than to small firms. In Feb 2024 an infrastructure bond seeking Ksh 70bn drew Ksh 288.7bn in bids; Ksh 240.9bn was taken.",
            source = "CBK; People Daily, Feb 2024"),
        quiz("ec-rate-cap", T, 4, "Kenya capped loan rates at CBR + 4% from 2016 to 2019. What happened to small-business credit?",
            listOf("It shrank: banks lent more to government", "It boomed", "It was unchanged", "SACCOs were banned"), 0,
            "Banks could not price riskier borrowers, so SMEs got less credit. The cap was repealed in November 2019.",
            source = "CBK; Finance Act 2019"),
        concept("ec-twin-deficits", T, 4, "What are \"twin deficits\"?",
            "A government spending more than it collects (fiscal deficit) and a country importing more than it earns abroad (current account deficit). Together they need steady foreign financing, which makes the shilling vulnerable.",
            source = "IMF"),
        concept("ec-yield-curve", T, 4, "What is the yield curve, and what does an upward slope mean?",
            "A line of yields from short (91-day bills) to long bonds. Upward means investors want more to lock money away longer, for inflation and risk. An inverted curve has often warned of recession elsewhere.",
            source = "CBK; Fed research"),

        // ---------- Level 5: Legend ----------
        quiz("ec-zimbabwe", T, 5, "Steve Hanke estimated Zimbabwe's inflation in November 2008. Per month, it was about:",
            listOf("79.6 billion percent", "79.6 percent", "7,960 percent", "796 thousand percent"), 0,
            "Prices roughly doubled every day. Zimbabwe printed a 100 trillion dollar note and in 2009 gave up its currency for the US dollar and rand.",
            source = "Hanke, Johns Hopkins, 2009"),
        concept("ec-zim-causes", T, 5, "What drove Zimbabwe's hyperinflation?",
            "The central bank printed money to fund government deficits while output collapsed, notably farm output after the land seizures. Too much money, too few goods, then a total loss of trust.",
            source = "Hanke & Kwok, Cato Journal, 2009"),
        quiz("ec-kenya-1993", T, 5, "Kenya's inflation averaged about how much in 1993?",
            listOf("About 46%", "About 6%", "About 460%", "About 16%"), 0,
            "Fast money growth around the 1992 election and the Goldenberg scandal fuelled it. Tight policy brought it down to low single digits by 1995.",
            source = "CBK; Business Daily"),
        concept("ec-goldenberg", T, 5, "What was the Goldenberg scandal?",
            "In the early 1990s Goldenberg International got export compensation for gold and diamond exports that were largely fictitious. Billions left the CBK, fuelling inflation. Whistleblower: David Munyakei.",
            source = "Bosire Commission"),
        concept("ec-2008-crisis", T, 5, "What triggered the 2008 global financial crisis?",
            "US banks made risky mortgages, bundled them into securities and borrowed heavily against them. When house prices fell, losses spread; Lehman Brothers failed on 15 September 2008 and credit froze worldwide.",
            source = "US Financial Crisis Inquiry Commission, 2011"),
        quiz("ec-great-depression", T, 5, "Friedman and Schwartz (1963) argued the Great Depression was made far worse by what?",
            listOf("The Fed letting the money supply shrink by about a third", "Too much government spending", "High oil prices", "The invention of credit cards"), 0,
            "Bank failures went unchecked and money vanished. Ben Bernanke later said, \"we did it... we won't do it again.\" It shaped how central banks fought 2008.",
            source = "Friedman & Schwartz, 1963"),
        concept("ec-cb-independence", T, 5, "Why are central banks made independent?",
            "Politicians may print or cut rates before elections. Alesina and Summers (1993) found more independent central banks had lower inflation with no loss of growth. Kenya's 2010 Constitution (Art. 231) protects CBK's independence.",
            source = "Alesina & Summers, 1993; Constitution of Kenya"),
        quiz("ec-mpesa-poverty", T, 5, "Suri and Jack (2016, Science) estimated M-Pesa did what in Kenya?",
            listOf("Lifted about 2% of households (194,000) out of poverty", "Doubled GDP", "Ended inflation", "Had no measurable effect"), 0,
            "Effects were strongest for women-headed households, through more saving and moving from farming into business. Some researchers dispute the size.",
            source = "Suri & Jack, Science, 2016"),
        quiz("ec-rebase-2014", T, 5, "In 2014 Kenya rebased its GDP statistics. What changed?",
            listOf("The economy measured about 25% bigger", "The shilling was redenominated", "Inflation was redefined", "GDP fell by half"), 0,
            "Updating the base year captured sectors like telecoms. Kenya was reclassified as lower-middle income. Nothing real changed overnight; the measurement did.",
            source = "KNBS, 2014"),
        concept("ec-cbk-1966", T, 5, "When did Kenya get its own central bank and currency?",
            "The Central Bank of Kenya was set up in 1966, and the Kenya shilling replaced the East African shilling that year. Before that, a regional currency board covered Kenya, Uganda and Tanzania.",
            source = "CBK"),
        quiz("ec-eurobond-2014", T, 5, "Kenya's debut Eurobond was issued in which year?",
            listOf("2014", "2004", "2019", "2008"), 0,
            "The 2014 deal raised USD 2bn initially (later tapped). Its 10-year portion due June 2024 was the bond that caused 2023 default fears.",
            source = "National Treasury; Bloomberg"),
        concept("ec-phillips", T, 5, "What is the Phillips curve, and why did the 1970s break it?",
            "Phillips (1958) found low unemployment went with faster wage growth, so policymakers thought they could trade a bit more inflation for jobs. 1970s oil shocks brought high inflation and high unemployment together: stagflation.",
            source = "Phillips, 1958; Friedman, 1968"),
    )
}
